// ─── File: CachingDemo.java ───
// Demonstrates gateway caching: public cache hit, per-user keying, invalidation.
package com.bank.gateway.demo;

import java.util.logging.*;

public class CachingDemo {
    private static final Logger log = Logger.getLogger("CachingGateway");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new CgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        CachingGateway gateway = new CachingGateway();

        log.info("=== Public rates (cacheable, shared) ===");
        gateway.get("/api/v1/rates", null);   // miss → backend
        gateway.get("/api/v1/rates", null);   // hit → cache

        log.info("=== Per-user balance (sensitive, keyed by user) ===");
        gateway.get("/api/v1/accounts/balance", "rajesh"); // miss
        gateway.get("/api/v1/accounts/balance", "rajesh"); // hit (Rajesh's own)
        gateway.get("/api/v1/accounts/balance", "priya");  // miss — different key, NO leakage

        log.info("=== Invalidation after a transfer ===");
        gateway.transferAndInvalidate("rajesh");
        gateway.get("/api/v1/accounts/balance", "rajesh"); // miss → fresh balance
    }
}

// ─── Would be in cache/CacheKey.java ───
class CacheKey {
    private final String method; private final String path; private final String user;
    CacheKey(String method, String path, String user) {
        this.method = method; this.path = path; this.user = user;
    }
    @Override public boolean equals(Object o) {
        if (!(o instanceof CacheKey)) return false;
        CacheKey k = (CacheKey) o;
        return java.util.Objects.equals(method, k.method)
            && java.util.Objects.equals(path, k.path)
            && java.util.Objects.equals(user, k.user); // user is part of the key → no cross-user leak
    }
    @Override public int hashCode() { return java.util.Objects.hash(method, path, user); }
    @Override public String toString() { return method + " " + path + (user == null ? " [public]" : " [user=" + user + "]"); }
}

// ─── Would be in cache/GatewayCache.java ───
class GatewayCache {
    private static class Entry { final String body; final long expiresAt;
        Entry(String body, long expiresAt) { this.body = body; this.expiresAt = expiresAt; } }
    private final java.util.Map<CacheKey, Entry> store = new java.util.concurrent.ConcurrentHashMap<>();

    void put(CacheKey key, String body, long ttlMs) {
        store.put(key, new Entry(body, System.currentTimeMillis() + ttlMs));
    }
    String get(CacheKey key) {
        Entry e = store.get(key);
        if (e == null) return null;
        if (System.currentTimeMillis() > e.expiresAt) { store.remove(key); return null; } // expired = stale guard
        return e.body;
    }
    void invalidate(CacheKey key) { store.remove(key); }
}

// ─── Would be in core/CachingGateway.java ───
class CachingGateway {
    private static final Logger log = Logger.getLogger("CachingGateway");
    private final GatewayCache cache = new GatewayCache();

    String get(String path, String user) {
        CachePolicy policy = policyFor(path);
        if (!policy.cacheable) {
            log.info(() -> "NO-CACHE " + path + " → always backend");
            return callBackend(path, user);
        }
        CacheKey key = new CacheKey("GET", path, policy.perUser ? user : null);
        String cached = cache.get(key);
        if (cached != null) { log.info(() -> "CACHE HIT  " + key); return cached; }
        log.info(() -> "CACHE MISS " + key + " → backend");
        String body = callBackend(path, user);
        cache.put(key, body, policy.ttlMs);
        return body;
    }

    // After a money movement, evict the affected user's cached balance.
    void transferAndInvalidate(String user) {
        log.info(() -> "Transfer done for " + user + " → invalidate cached balance");
        cache.invalidate(new CacheKey("GET", "/api/v1/accounts/balance", user));
    }

    private CachePolicy policyFor(String path) {
        if (path.startsWith("/api/v1/rates")) return new CachePolicy(true, false, 60000); // public, 60s
        if (path.endsWith("/balance")) return new CachePolicy(true, true, 5000);           // per-user, 5s
        return new CachePolicy(false, false, 0);                                           // default no-cache
    }

    private String callBackend(String path, String user) {
        if (path.startsWith("/api/v1/rates")) return "{fd:6.75%, savings:3.0%}";
        if (path.endsWith("/balance")) return user == null ? "{}" : "{user:" + user + ", balance:" + bal(user) + "}";
        return "{}";
    }
    private String bal(String user) { return "rajesh".equals(user) ? "1000000" : "250000"; }
}

// ─── Would be in core/CachePolicy.java ───
class CachePolicy {
    final boolean cacheable; final boolean perUser; final long ttlMs;
    CachePolicy(boolean cacheable, boolean perUser, long ttlMs) {
        this.cacheable = cacheable; this.perUser = perUser; this.ttlMs = ttlMs;
    }
}

